"""Workflow patching tools.

Apply RFC6902 JSON patches to ComfyUI workflows with full undo support.
The agent reasons about what changes to make, then calls these tools
with concrete patch operations.

State is module-level: load a workflow once, patch it multiple times,
undo as needed, then save or execute.
"""

import copy
import json
from pathlib import Path

import jsonpatch

from ._util import to_json

# ---------------------------------------------------------------------------
# Module-level state (one active workflow at a time)
# ---------------------------------------------------------------------------
# WorkflowSession is dict-like: _state["key"] and _state.get("key") work.
# The lock is per-session, so the existing `with _state_lock:` pattern
# continues to work for the default session.

from ..workflow_session import get_session

_state = get_session("default")
_state_lock = _state._lock


def _ensure_loaded() -> str | None:
    """Return error message if no workflow is loaded, else None."""
    if _state["current_workflow"] is None:
        return "No workflow loaded. Use apply_workflow_patch with a file path first."
    return None


def _load_workflow(path_str: str) -> str | None:
    """Load a workflow into state. Returns error or None."""
    from ._util import validate_path
    path_err = validate_path(path_str, must_exist=True)
    if path_err:
        return path_err
    path = Path(path_str)

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        return f"Invalid JSON: {e}"

    # Extract API format
    if "nodes" in data and isinstance(data["nodes"], list):
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            api_nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            _state["format"] = "ui_with_api"
        else:
            return (
                "UI-only workflow format -- can't patch without API data. "
                "Re-export using 'Save (API Format)' in ComfyUI."
            )
    else:
        api_nodes = {
            k: v for k, v in data.items()
            if isinstance(v, dict) and "class_type" in v
        }
        _state["format"] = "api"

    if not api_nodes:
        return "No nodes found in workflow."

    _state["loaded_path"] = path_str
    _state["base_workflow"] = copy.deepcopy(api_nodes)
    _state["current_workflow"] = copy.deepcopy(api_nodes)
    _state["history"] = []
    return None


# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "apply_workflow_patch",
        "description": (
            "Apply RFC6902 JSON patches to a workflow. If no workflow is "
            "loaded yet, provide the file path to load it first. "
            "Patches use the format: "
            '[{"op": "replace", "path": "/node_id/inputs/field", "value": new_value}]. '
            "Returns the changes made and the current state of affected fields. "
            "Supports undo via undo_workflow_patch."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": (
                        "Path to workflow JSON file. Required on first call, "
                        "optional after (reuses loaded workflow)."
                    ),
                },
                "patches": {
                    "type": "array",
                    "description": (
                        "RFC6902 patch operations. Each has 'op' (usually 'replace'), "
                        "'path' (e.g. '/5/inputs/text'), and 'value'."
                    ),
                    "items": {
                        "type": "object",
                        "properties": {
                            "op": {"type": "string"},
                            "path": {"type": "string"},
                            "value": {},
                        },
                        "required": ["op", "path", "value"],
                    },
                },
            },
            "required": ["patches"],
        },
    },
    {
        "name": "preview_workflow_patch",
        "description": (
            "Preview what a patch would change WITHOUT applying it. "
            "Shows before/after values for each affected field."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "patches": {
                    "type": "array",
                    "description": "RFC6902 patch operations to preview.",
                    "items": {
                        "type": "object",
                        "properties": {
                            "op": {"type": "string"},
                            "path": {"type": "string"},
                            "value": {},
                        },
                        "required": ["op", "path", "value"],
                    },
                },
            },
            "required": ["patches"],
        },
    },
    {
        "name": "undo_workflow_patch",
        "description": (
            "Undo the last patch operation. Can be called multiple times "
            "to step back through history."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_workflow_diff",
        "description": (
            "Show all changes from the original workflow as a JSON patch diff. "
            "Useful for reviewing everything that's been modified."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "save_workflow",
        "description": (
            "Save the current (patched) workflow to a file. "
            "If no output path is given, overwrites the original."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "output_path": {
                    "type": "string",
                    "description": (
                        "Path to save the workflow. If omitted, overwrites the original file."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "reset_workflow",
        "description": (
            "Reset the workflow back to its original state, discarding all patches."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    # --- Semantic composition tools ---
    {
        "name": "add_node",
        "description": (
            "Add a new node to the loaded workflow. Assigns a unique node ID "
            "and sets up the node with the given class_type and optional input values. "
            "Returns the assigned node_id so you can connect it to other nodes. "
            "A workflow must be loaded first (via apply_workflow_patch or load from template)."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "class_type": {
                    "type": "string",
                    "description": "Node class_type (e.g. 'KSampler', 'CLIPTextEncode', 'CheckpointLoaderSimple').",
                },
                "inputs": {
                    "type": "object",
                    "description": (
                        "Optional initial input values. Keys are input names, "
                        "values are literals (int, float, str). Connections should "
                        "be set separately with connect_nodes."
                    ),
                },
            },
            "required": ["class_type"],
        },
    },
    {
        "name": "connect_nodes",
        "description": (
            "Connect one node's output to another node's input. "
            "This sets the connection in the workflow graph. "
            "Example: connect KSampler output 0 to VAEDecode input 'samples'."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "from_node": {
                    "type": "string",
                    "description": "Source node ID (the node producing the output).",
                },
                "from_output": {
                    "type": "integer",
                    "description": "Output index on the source node (usually 0).",
                },
                "to_node": {
                    "type": "string",
                    "description": "Target node ID (the node receiving the input).",
                },
                "to_input": {
                    "type": "string",
                    "description": "Input name on the target node (e.g. 'model', 'samples', 'clip').",
                },
            },
            "required": ["from_node", "from_output", "to_node", "to_input"],
        },
    },
    {
        "name": "set_input",
        "description": (
            "Set a literal input value on a node. For connections between nodes, "
            "use connect_nodes instead. This is for values like seed, steps, "
            "cfg, sampler_name, prompt text, model filenames, etc."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "node_id": {
                    "type": "string",
                    "description": "Target node ID.",
                },
                "input_name": {
                    "type": "string",
                    "description": "Input field name (e.g. 'seed', 'steps', 'text', 'ckpt_name').",
                },
                "value": {
                    "description": "The value to set (string, int, float, bool).",
                },
            },
            "required": ["node_id", "input_name", "value"],
        },
    },
]

# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _get_value_at_path(workflow: dict, path: str):
    """Navigate a JSON path and return the value, or None."""
    parts = path.strip("/").split("/")
    current = workflow
    for part in parts:
        if isinstance(current, dict):
            current = current.get(part)
        elif isinstance(current, list) and part.isdigit():
            idx = int(part)
            current = current[idx] if idx < len(current) else None
        else:
            return None
        if current is None:
            return None
    return current


def _handle_apply_patch(tool_input: dict) -> str:
    path_str = tool_input.get("path")
    patches = tool_input["patches"]

    # Load workflow if path provided or not loaded yet
    if path_str:
        err = _load_workflow(path_str)
        if err:
            return to_json({"error": err})
    elif _state["current_workflow"] is None:
        return to_json({
            "error": "No workflow loaded. Provide a 'path' to load one first."
        })

    # Record before values for the diff report
    before_values = {}
    for patch in patches:
        p = patch.get("path", "")
        before_values[p] = _get_value_at_path(_state["current_workflow"], p)

    # Save current state for undo
    _state["history"].append(copy.deepcopy(_state["current_workflow"]))

    # Apply patches
    try:
        jp = jsonpatch.JsonPatch(patches)
        _state["current_workflow"] = jp.apply(_state["current_workflow"])
    except Exception as e:
        # Rollback on failure
        _state["current_workflow"] = _state["history"].pop()
        return to_json({"error": f"Patch failed: {e}"})

    # Build change report
    changes = []
    for patch in patches:
        p = patch.get("path", "")
        changes.append({
            "path": p,
            "op": patch.get("op"),
            "before": before_values.get(p),
            "after": patch.get("value"),
        })

    return to_json({
        "applied": len(patches),
        "changes": changes,
        "undo_available": True,
        "total_changes_from_base": len(
            jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
        ),
    })


def _handle_preview_patch(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    patches = tool_input["patches"]

    # Preview without modifying state
    preview = []
    try:
        jp = jsonpatch.JsonPatch(patches)
        jp.apply(copy.deepcopy(_state["current_workflow"]))
    except Exception as e:
        return to_json({"error": f"Patch would fail: {e}"})

    for patch in patches:
        p = patch.get("path", "")
        preview.append({
            "path": p,
            "op": patch.get("op"),
            "current_value": _get_value_at_path(_state["current_workflow"], p),
            "new_value": patch.get("value"),
        })

    return to_json({"preview": preview, "would_succeed": True})


def _handle_undo() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    if not _state["history"]:
        return to_json({"error": "Nothing to undo."})

    _state["current_workflow"] = _state["history"].pop()

    remaining = len(
        jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
    )
    return to_json({
        "undone": True,
        "remaining_changes_from_base": remaining,
        "undo_steps_remaining": len(_state["history"]),
    })


def _handle_get_diff() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    diff = jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch

    if not diff:
        return to_json({"changes": 0, "message": "No changes from original."})

    return to_json({
        "changes": len(diff),
        "diff": diff,
        "loaded_from": _state["loaded_path"],
    })


def _handle_save(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    output_path = tool_input.get("output_path") or _state["loaded_path"]
    if not output_path:
        return to_json({"error": "No output path specified."})

    from ._util import validate_path
    path_err = validate_path(output_path)
    if path_err:
        return to_json({"error": path_err})

    try:
        Path(output_path).write_text(
            to_json(_state["current_workflow"], indent=2),
            encoding="utf-8",
        )
    except Exception as e:
        return to_json({"error": f"Failed to save: {e}"})

    changes = len(
        jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
    )
    return to_json({
        "saved": output_path,
        "changes_from_base": changes,
    })


def _handle_reset() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    _state["current_workflow"] = copy.deepcopy(_state["base_workflow"])
    _state["history"] = []

    return to_json({
        "reset": True,
        "loaded_from": _state["loaded_path"],
    })


# ---------------------------------------------------------------------------
# Semantic composition handlers
# ---------------------------------------------------------------------------

def _next_node_id() -> str:
    """Find the next available numeric node ID."""
    workflow = _state["current_workflow"]
    if not workflow:
        return "1"
    existing = set()
    for key in workflow:
        try:
            existing.add(int(key))
        except ValueError:
            pass
    next_id = max(existing, default=0) + 1
    return str(next_id)


def _handle_add_node(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    class_type = tool_input["class_type"]
    inputs = tool_input.get("inputs", {})

    # Save state for undo
    _state["history"].append(copy.deepcopy(_state["current_workflow"]))

    node_id = _next_node_id()
    _state["current_workflow"][node_id] = {
        "class_type": class_type,
        "inputs": inputs,
    }

    return to_json({
        "added": True,
        "node_id": node_id,
        "class_type": class_type,
        "inputs": inputs,
        "total_nodes": len(_state["current_workflow"]),
    })


def _handle_connect_nodes(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    from_node = tool_input["from_node"]
    from_output = tool_input["from_output"]
    to_node = tool_input["to_node"]
    to_input = tool_input["to_input"]

    workflow = _state["current_workflow"]

    # Validate nodes exist
    if from_node not in workflow:
        return to_json({"error": f"Source node '{from_node}' not found in workflow."})
    if to_node not in workflow:
        return to_json({"error": f"Target node '{to_node}' not found in workflow."})

    # Save state for undo
    _state["history"].append(copy.deepcopy(workflow))

    # Set connection (ComfyUI format: [source_node_id_str, output_index_int])
    old_value = workflow[to_node].get("inputs", {}).get(to_input)
    workflow[to_node].setdefault("inputs", {})[to_input] = [from_node, from_output]

    from_class = workflow[from_node].get("class_type", "?")
    to_class = workflow[to_node].get("class_type", "?")

    return to_json({
        "connected": True,
        "from": f"{from_class} [{from_node}] output {from_output}",
        "to": f"{to_class} [{to_node}].{to_input}",
        "previous_value": old_value,
    })


def _handle_set_input(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    node_id = tool_input["node_id"]
    input_name = tool_input["input_name"]
    value = tool_input["value"]

    workflow = _state["current_workflow"]

    if node_id not in workflow:
        return to_json({"error": f"Node '{node_id}' not found in workflow."})

    # Save state for undo
    _state["history"].append(copy.deepcopy(workflow))

    old_value = workflow[node_id].get("inputs", {}).get(input_name)
    workflow[node_id].setdefault("inputs", {})[input_name] = value

    class_type = workflow[node_id].get("class_type", "?")

    return to_json({
        "set": True,
        "node": f"{class_type} [{node_id}]",
        "input": input_name,
        "old_value": old_value,
        "new_value": value,
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a workflow_patch tool call."""
    with _state_lock:
        try:
            if name == "apply_workflow_patch":
                return _handle_apply_patch(tool_input)
            elif name == "preview_workflow_patch":
                return _handle_preview_patch(tool_input)
            elif name == "undo_workflow_patch":
                return _handle_undo()
            elif name == "get_workflow_diff":
                return _handle_get_diff()
            elif name == "save_workflow":
                return _handle_save(tool_input)
            elif name == "reset_workflow":
                return _handle_reset()
            elif name == "add_node":
                return _handle_add_node(tool_input)
            elif name == "connect_nodes":
                return _handle_connect_nodes(tool_input)
            elif name == "set_input":
                return _handle_set_input(tool_input)
            else:
                return to_json({"error": f"Unknown tool: {name}"})
        except Exception as e:
            return to_json({"error": str(e)})


def get_current_workflow() -> dict | None:
    """Get the current workflow dict (used by comfy_execute)."""
    return _state["current_workflow"]

"""Workflow analysis tools.

Load, analyze, summarize, and validate ComfyUI workflow JSON.
Handles both UI format (from ComfyUI "Save") and API format
(from "Save API Format" or programmatic use).

These tools give the agent deep understanding of what a workflow does,
what's connected to what, and what can be safely modified.
"""

import json
from pathlib import Path

import httpx

from ._util import to_json
from ..config import COMFYUI_URL

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "load_workflow",
        "description": (
            "Load and analyze a ComfyUI workflow JSON file. "
            "Returns: format type, all nodes with class_type, "
            "connections between nodes (the graph), editable fields "
            "with current values, and a human-readable summary of the pipeline. "
            "This is the main tool for understanding what a workflow does."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "validate_workflow",
        "description": (
            "Validate a workflow against the running ComfyUI instance. "
            "Checks that all node types exist (are installed), that required "
            "inputs are provided, and that connections have compatible types. "
            "Requires ComfyUI to be running."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
            },
            "required": ["path"],
        },
    },
    {
        "name": "get_editable_fields",
        "description": (
            "Get a focused list of all editable fields in a workflow — "
            "the parameters that can be changed without rewiring the graph. "
            "Groups fields by node class_type for easy scanning. "
            "This is useful before modifying a workflow."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": "Absolute path to the workflow JSON file.",
                },
                "class_filter": {
                    "type": "string",
                    "description": (
                        "Optional: only show fields from nodes matching this "
                        "class_type substring (case-insensitive)."
                    ),
                },
            },
            "required": ["path"],
        },
    },
]

# ---------------------------------------------------------------------------
# Core parsing logic
# ---------------------------------------------------------------------------


def _load_json(path_str: str) -> tuple[dict, str | None]:
    """Load JSON from file. Returns (data, error_or_none)."""
    path = Path(path_str)
    if not path.exists():
        return {}, f"File not found: {path_str}"
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        return data, None
    except json.JSONDecodeError as e:
        return {}, f"Invalid JSON: {e}"


def _extract_api_format(data: dict) -> tuple[dict, str]:
    """
    Extract API-format node dict from any workflow format.

    Returns (api_nodes, format_name).
    api_nodes: {node_id_str: {"class_type": ..., "inputs": {...}}}
    """
    # Check for UI format (has "nodes" array)
    if "nodes" in data and isinstance(data["nodes"], list):
        # Prefer embedded API format in extra.prompt
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            return nodes, "ui_with_api"

        # UI-only: convert nodes array
        nodes = {}
        for node in data["nodes"]:
            nid = str(node.get("id", ""))
            class_type = node.get("type", "Unknown")
            widgets = node.get("widgets_values", [])
            nodes[nid] = {
                "class_type": class_type,
                "inputs": {},
                "_widgets_values": widgets,
                "_ui_node": True,
            }
        return nodes, "ui_only"

    # API format: top-level keys are node IDs
    nodes = {
        k: v for k, v in data.items()
        if isinstance(v, dict) and "class_type" in v
    }
    return nodes, "api"


def _trace_connections(nodes: dict) -> list[dict]:
    """
    Trace connections between nodes.

    In API format, a connection is an input value that's a list:
    [source_node_id_str, output_index_int]

    Returns list of connection dicts.
    """
    connections = []
    for target_id, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue  # UI-only nodes don't have connection info
        for input_name, value in sorted(node.get("inputs", {}).items()):
            if isinstance(value, list) and len(value) == 2:
                source_id = str(value[0])
                output_idx = value[1]
                source_class = nodes.get(source_id, {}).get("class_type", "?")
                target_class = node.get("class_type", "?")
                connections.append({
                    "from_node": source_id,
                    "from_class": source_class,
                    "from_output": output_idx,
                    "to_node": target_id,
                    "to_class": target_class,
                    "to_input": input_name,
                })
    return connections


def _find_editable_fields(nodes: dict, class_filter: str = "") -> list[dict]:
    """
    Find all non-connection input fields (the editable parameters).
    """
    fields = []
    filter_lower = class_filter.lower()

    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")
        if filter_lower and filter_lower not in class_type.lower():
            continue

        # He2025: sort for deterministic field order per node
        for field_name, value in sorted(node.get("inputs", {}).items()):
            # Skip connections (2-element list [node_id, output_index])
            if isinstance(value, list) and len(value) == 2:
                continue

            fields.append({
                "node_id": nid,
                "class_type": class_type,
                "field": field_name,
                "value": value,
                "type": type(value).__name__,
            })

    return fields


def _build_summary(nodes: dict, connections: list[dict], fmt: str) -> str:
    """Build a human-readable summary of the workflow pipeline."""
    if not nodes:
        return "Empty workflow (no nodes found)."

    lines = []

    # Class type counts
    class_counts: dict[str, int] = {}
    for node in nodes.values():
        ct = node.get("class_type", "Unknown")
        class_counts[ct] = class_counts.get(ct, 0) + 1

    lines.append(f"{len(nodes)} nodes, {len(connections)} connections")
    lines.append("")

    # Identify pipeline stages by looking at node classes
    loaders = []
    encoders = []
    samplers = []
    threed = []
    outputs = []
    other = []

    for ct in sorted(class_counts.keys()):
        ct_lower = ct.lower()
        if any(k in ct_lower for k in ("load", "checkpoint", "unet", "model")):
            loaders.append(ct)
        elif any(k in ct_lower for k in ("encode", "clip", "conditioning")):
            encoders.append(ct)
        elif any(k in ct_lower for k in ("sample", "sampler", "ksampler", "denoise")):
            samplers.append(ct)
        elif any(k in ct_lower for k in (
            "mesh", "voxel", "3d", "triplane", "gaussian", "splat",
            "point_cloud", "glb", "ply", "obj", "nerf",
            "pose", "camera", "hunyuan3d",
        )):
            threed.append(ct)
        elif any(k in ct_lower for k in ("save", "preview", "output", "combine", "video")):
            outputs.append(ct)
        else:
            other.append(ct)

    if loaders:
        lines.append(f"Loaders: {', '.join(loaders)}")
    if encoders:
        lines.append(f"Encoding: {', '.join(encoders)}")
    if samplers:
        lines.append(f"Sampling: {', '.join(samplers)}")
    if threed:
        lines.append(f"3D Processing: {', '.join(threed)}")
    if outputs:
        lines.append(f"Output: {', '.join(outputs)}")
    if other:
        lines.append(f"Other: {', '.join(other)}")

    # Describe data flow from connections
    if connections:
        lines.append("")
        lines.append("Data flow:")
        # Group by target node to show input sources
        by_target: dict[str, list[dict]] = {}
        for conn in connections:
            key = f"{conn['to_node']} ({conn['to_class']})"
            by_target.setdefault(key, []).append(conn)

        for target, conns in sorted(by_target.items()):
            sources = [f"{c['from_class']}.out[{c['from_output']}]" for c in conns]
            lines.append(f"  {target} <- {', '.join(sources)}")

    if fmt == "ui_only":
        lines.append("")
        lines.append(
            "Note: UI-only format — editable field values not available. "
            "Use an API-format workflow for full analysis."
        )

    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Validation (requires live ComfyUI)
# ---------------------------------------------------------------------------

def _validate_against_comfyui(nodes: dict, connections: list[dict]) -> dict:
    """Validate workflow against running ComfyUI instance."""
    errors = []
    warnings = []

    # Fetch all node info
    try:
        with httpx.Client() as client:
            resp = client.get(f"{COMFYUI_URL}/object_info", timeout=30.0)
            resp.raise_for_status()
            all_info = resp.json()
    except httpx.ConnectError:
        return {"error": f"ComfyUI not reachable at {COMFYUI_URL}. Is it running?"}
    except Exception as e:
        return {"error": str(e)}

    # Check each node
    # He2025: sort for deterministic error order
    for nid, node in sorted(nodes.items()):
        if node.get("_ui_node"):
            continue
        class_type = node.get("class_type", "")

        # Check node type exists
        if class_type not in all_info:
            errors.append(f"Node [{nid}]: class_type '{class_type}' not installed.")
            continue

        node_schema = all_info[class_type]
        required_inputs = node_schema.get("input", {}).get("required", {})
        optional_inputs = node_schema.get("input", {}).get("optional", {})
        all_known_inputs = {**required_inputs, **optional_inputs}

        # Check required inputs are provided
        node_inputs = node.get("inputs", {})
        for req_name in required_inputs:
            if req_name not in node_inputs:
                errors.append(
                    f"Node [{nid}] {class_type}: missing required input '{req_name}'."
                )

        # Check for unknown inputs
        for inp_name in node_inputs:
            if inp_name not in all_known_inputs:
                warnings.append(
                    f"Node [{nid}] {class_type}: unknown input '{inp_name}' "
                    f"(may be from a different version)."
                )

    # Check connection type compatibility
    for conn in connections:
        source_class = conn["from_class"]
        output_idx = conn["from_output"]
        target_class = conn["to_class"]
        target_input = conn["to_input"]

        # Get source output types
        source_info = all_info.get(source_class, {})
        source_outputs = source_info.get("output", [])
        if output_idx < len(source_outputs):
            source_type = source_outputs[output_idx]
        else:
            errors.append(
                f"Connection {source_class}[{output_idx}] → "
                f"{target_class}.{target_input}: output index out of range."
            )
            continue

        # Get target input type
        target_info = all_info.get(target_class, {})
        all_target_inputs = {
            **target_info.get("input", {}).get("required", {}),
            **target_info.get("input", {}).get("optional", {}),
        }
        target_spec = all_target_inputs.get(target_input)
        if target_spec and isinstance(target_spec, (list, tuple)) and len(target_spec) > 0:
            target_type = target_spec[0]
            # Check type compatibility (exact match or wildcard "*")
            if (
                isinstance(target_type, str)
                and isinstance(source_type, str)
                and target_type != "*"
                and source_type != "*"
                and source_type != target_type
            ):
                errors.append(
                    f"Type mismatch: {source_class}.out[{output_idx}] "
                    f"({source_type}) → {target_class}.{target_input} "
                    f"(expects {target_type})."
                )

    return {
        "valid": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
    }


# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _handle_load_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    connections = _trace_connections(nodes)
    editable = _find_editable_fields(nodes)
    summary = _build_summary(nodes, connections, fmt)

    # Build node list for output
    node_list = {}
    for nid, node in nodes.items():
        entry = {
            "class_type": node.get("class_type", ""),
        }
        if not node.get("_ui_node"):
            entry["input_count"] = len(node.get("inputs", {}))
        node_list[nid] = entry

    return to_json({
        "file": path_str,
        "format": fmt,
        "node_count": len(nodes),
        "connection_count": len(connections),
        "editable_field_count": len(editable),
        "summary": summary,
        "nodes": node_list,
        "connections": connections,
        "editable_fields": editable,
    })


def _handle_validate_workflow(tool_input: dict) -> str:
    path_str = tool_input["path"]
    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only workflow format — can't validate without API format data. "
                "Re-export the workflow using 'Save (API Format)' in ComfyUI, "
                "or use a workflow that has extra.prompt embedded."
            ),
        })

    connections = _trace_connections(nodes)
    result = _validate_against_comfyui(nodes, connections)
    return to_json(result)


def _handle_get_editable_fields(tool_input: dict) -> str:
    path_str = tool_input["path"]
    class_filter = tool_input.get("class_filter", "")

    data, err = _load_json(path_str)
    if err:
        return to_json({"error": err})

    nodes, fmt = _extract_api_format(data)
    if fmt == "ui_only":
        return to_json({
            "error": (
                "UI-only format — field values aren't available. "
                "Use an API-format workflow or one with extra.prompt embedded."
            ),
        })

    fields = _find_editable_fields(nodes, class_filter)

    # Group by class_type for readability
    by_class: dict[str, list[dict]] = {}
    for f in fields:
        by_class.setdefault(f["class_type"], []).append(f)

    return to_json({
        "file": path_str,
        "total_fields": len(fields),
        "fields_by_class": by_class,
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a workflow_parse tool call."""
    try:
        if name == "load_workflow":
            return _handle_load_workflow(tool_input)
        elif name == "validate_workflow":
            return _handle_validate_workflow(tool_input)
        elif name == "get_editable_fields":
            return _handle_get_editable_fields(tool_input)
        else:
            return to_json({"error": f"Unknown tool: {name}"})
    except Exception as e:
        return to_json({"error": str(e)})

"""SUPER DUPER UI -- aiohttp routes mounted on ComfyUI's PromptServer.

Provides:
  POST /superduper/chat   -- synchronous chat (request/response)
  GET  /superduper/status  -- agent and connection state
  GET  /superduper/ws      -- WebSocket for real-time streaming
"""

import asyncio
import json
import logging
import queue
import sys
import threading
import uuid
from pathlib import Path

from aiohttp import web

log = logging.getLogger("superduper.routes")

# ---------------------------------------------------------------------------
# Agent brain import (lazy — ComfyUI loads us before agent is on sys.path)
# ---------------------------------------------------------------------------

_brain_lock = threading.Lock()
_brain_ready = False
_client = None


def _ensure_brain():
    """Lazily import the agent brain and create the Anthropic client."""
    global _brain_ready, _client
    if _brain_ready:
        return True

    with _brain_lock:
        if _brain_ready:
            return True

        try:
            # Add project root to path so `agent` package is importable
            project_root = str(Path(__file__).resolve().parent.parent.parent)
            if project_root not in sys.path:
                sys.path.insert(0, project_root)

            from agent.main import create_client
            _client = create_client()
            _brain_ready = True
            log.info("Agent brain loaded, Anthropic client ready")
            return True
        except Exception as e:
            log.error("Failed to load agent brain: %s", e)
            return False


# ---------------------------------------------------------------------------
# Per-connection conversation state
# ---------------------------------------------------------------------------

class ConversationState:
    """Tracks one sidebar conversation."""

    def __init__(self):
        self.id = str(uuid.uuid4())[:8]
        self.messages: list[dict] = []
        self.system_prompt: str | None = None
        self.busy = False
        self.lock = threading.Lock()

    def _build_system(self):
        if self.system_prompt is None:
            from agent.system_prompt import build_system_prompt
            self.system_prompt = build_system_prompt()


# Active conversations keyed by connection ID
_conversations: dict[str, ConversationState] = {}


# ---------------------------------------------------------------------------
# Synchronous agent runner (called from thread)
# ---------------------------------------------------------------------------

def _run_agent_sync(conv: ConversationState, user_text: str, msg_queue: queue.Queue):
    """Run the agent loop synchronously, pushing events to msg_queue.

    Events are dicts: {"type": "text_delta"|"tool_call"|"stage"|"done"|"error", ...}
    """
    from agent.main import run_agent_turn
    from agent.tools import ALL_TOOLS

    conv._build_system()
    conv.messages.append({"role": "user", "content": user_text})

    max_turns = 15  # safety limit per user message

    for turn in range(max_turns):
        try:
            def on_text(text):
                msg_queue.put({"type": "text_delta", "text": text})

            def on_tool(name, inp):
                # Infer stage from tool name
                stage = _infer_stage(name)
                msg_queue.put({
                    "type": "tool_call",
                    "tool": name,
                    "stage": stage,
                })

            conv.messages, done = run_agent_turn(
                _client,
                conv.messages,
                conv.system_prompt,
                on_text_delta=on_text,
                on_tool_call=on_tool,
            )

            if done:
                msg_queue.put({"type": "done"})
                return

        except Exception as e:
            log.error("Agent turn error: %s", e, exc_info=True)
            msg_queue.put({"type": "error", "message": str(e)})
            return

    msg_queue.put({"type": "done"})


def _infer_stage(tool_name: str) -> str:
    """Map tool name to intelligence layer stage."""
    understand = {
        "load_workflow", "validate_workflow", "get_editable_fields",
        "is_comfyui_running", "get_all_nodes", "get_node_info",
        "get_system_stats", "get_queue_status", "get_history",
        "list_custom_nodes", "list_models", "get_models_summary",
        "read_node_source",
    }
    discover = {
        "discover", "find_missing_nodes", "check_registry_freshness",
        "get_install_instructions", "get_civitai_model", "get_trending_models",
        "list_workflow_templates", "get_workflow_template",
        "check_node_updates", "get_repo_releases",
        "identify_model_family", "check_model_compatibility",
    }
    pilot = {
        "apply_workflow_patch", "preview_workflow_patch", "undo_workflow_patch",
        "get_workflow_diff", "save_workflow", "reset_workflow",
        "add_node", "connect_nodes", "set_input",
        "save_session", "load_session", "list_sessions", "add_note",
    }
    verify = {
        "validate_before_execute", "execute_workflow",
        "get_execution_status", "execute_with_progress",
        "get_output_path", "verify_execution",
    }

    if tool_name in understand:
        return "UNDERSTAND"
    elif tool_name in discover:
        return "DISCOVER"
    elif tool_name in pilot:
        return "PILOT"
    elif tool_name in verify:
        return "VERIFY"
    else:
        return "BRAIN"


# ---------------------------------------------------------------------------
# WebSocket handler
# ---------------------------------------------------------------------------

async def websocket_handler(request):
    """Bidirectional WebSocket for real-time sidebar <-> agent communication."""
    ws = web.WebSocketResponse()
    await ws.prepare(request)

    if not _ensure_brain():
        await ws.send_json({
            "type": "error",
            "message": "Agent brain failed to load. Check logs.",
        })
        await ws.close()
        return ws

    conv = ConversationState()
    _conversations[conv.id] = conv

    await ws.send_json({
        "type": "connected",
        "conversation_id": conv.id,
    })

    log.info("WebSocket connected: %s", conv.id)

    try:
        async for raw_msg in ws:
            if raw_msg.type in (web.WSMsgType.TEXT,):
                try:
                    data = json.loads(raw_msg.data)
                except json.JSONDecodeError:
                    await ws.send_json({"type": "error", "message": "Invalid JSON"})
                    continue

                msg_type = data.get("type", "")

                if msg_type == "chat":
                    content = data.get("content", "").strip()
                    if not content:
                        continue

                    if conv.busy:
                        await ws.send_json({
                            "type": "error",
                            "message": "Agent is still processing. Please wait.",
                        })
                        continue

                    conv.busy = True
                    await ws.send_json({"type": "stage", "stage": "THINKING", "detail": ""})

                    # Run agent in background thread, stream results back
                    msg_queue = queue.Queue()
                    loop = asyncio.get_running_loop()

                    thread = threading.Thread(
                        target=_run_agent_sync,
                        args=(conv, content, msg_queue),
                        daemon=True,
                    )
                    thread.start()

                    # Drain the queue and forward events to WebSocket
                    accumulated_text = []
                    while True:
                        try:
                            event = await loop.run_in_executor(
                                None, lambda: msg_queue.get(timeout=0.1)
                            )
                        except queue.Empty:
                            if not thread.is_alive():
                                # Thread finished — drain remaining
                                while not msg_queue.empty():
                                    event = msg_queue.get_nowait()
                                    await _forward_event(ws, event, accumulated_text)
                                break
                            continue

                        await _forward_event(ws, event, accumulated_text)

                        if event["type"] in ("done", "error"):
                            break

                    # Send final assembled message
                    if accumulated_text:
                        full_text = "".join(accumulated_text)
                        await ws.send_json({
                            "type": "message",
                            "role": "agent",
                            "content": full_text,
                        })

                    conv.busy = False

                elif msg_type == "approve":
                    # Phase 4: patch approval
                    pass

                elif msg_type == "reject":
                    # Phase 4: patch rejection
                    pass

            elif raw_msg.type == web.WSMsgType.ERROR:
                log.error("WebSocket error: %s", ws.exception())

    finally:
        _conversations.pop(conv.id, None)
        log.info("WebSocket disconnected: %s", conv.id)

    return ws


async def _forward_event(ws, event, accumulated_text):
    """Forward an agent event to the WebSocket client."""
    etype = event["type"]

    if etype == "text_delta":
        # Accumulate text (we send the full message at the end)
        accumulated_text.append(event["text"])
        # Also send delta for live streaming
        await ws.send_json({
            "type": "text_delta",
            "text": event["text"],
        })

    elif etype == "tool_call":
        await ws.send_json({
            "type": "stage",
            "stage": event.get("stage", "THINKING"),
            "detail": f"Using {event['tool']}...",
        })

    elif etype == "error":
        await ws.send_json({
            "type": "error",
            "message": event.get("message", "Unknown error"),
            "recoverable": True,
        })

    elif etype == "done":
        await ws.send_json({"type": "stage", "stage": "DONE", "detail": ""})


# ---------------------------------------------------------------------------
# REST endpoints
# ---------------------------------------------------------------------------

async def handle_chat(request):
    """POST /superduper/chat -- simple request/response chat."""
    if not _ensure_brain():
        return web.json_response(
            {"error": "Agent brain not available"}, status=503
        )

    data = await request.json()
    content = data.get("content", "").strip()
    if not content:
        return web.json_response({"error": "Empty message"}, status=400)

    # Use a temporary conversation for REST endpoint
    conv = ConversationState()
    msg_queue = queue.Queue()

    loop = asyncio.get_running_loop()
    await loop.run_in_executor(
        None, _run_agent_sync, conv, content, msg_queue
    )

    # Collect all text
    text_parts = []
    stage = "DONE"
    while not msg_queue.empty():
        event = msg_queue.get_nowait()
        if event["type"] == "text_delta":
            text_parts.append(event["text"])
        elif event["type"] == "tool_call":
            stage = event.get("stage", stage)

    return web.json_response({
        "role": "agent",
        "content": "".join(text_parts),
        "stage": stage,
    })


async def handle_status(request):
    """GET /superduper/status -- agent and connection state."""
    brain_ok = _ensure_brain()
    return web.json_response({
        "brain": "ready" if brain_ok else "unavailable",
        "active_conversations": len(_conversations),
        "conversations": [
            {"id": c.id, "busy": c.busy, "messages": len(c.messages)}
            for c in _conversations.values()
        ],
    })


# ---------------------------------------------------------------------------
# Route setup (called from ui/__init__.py at import time)
# ---------------------------------------------------------------------------

def setup_routes():
    """Mount all SUPER DUPER routes on ComfyUI's PromptServer."""
    try:
        from server import PromptServer
        routes = PromptServer.instance.routes
        routes.post("/superduper/chat")(handle_chat)
        routes.get("/superduper/status")(handle_status)
        routes.get("/superduper/ws")(websocket_handler)
        log.info("SUPER DUPER routes mounted: /superduper/chat, /superduper/status, /superduper/ws")
    except Exception as e:
        log.error("Failed to mount SUPER DUPER routes: %s", e)

